//! TypeScript bindings generation (see `docs/adr/0004-bindings-generation.md`).
//!
//! `src/ipc/bindings.ts` is generated from this module by the
//! `export-bindings` binary (`pnpm bindings`). Never edit it by hand.
//!
//! Adding a command: register its DTOs in `declarations` and its signature in
//! `commands`. Argument names are the camelCase form Tauri expects from JS.

use ts_rs::{Config, TS};

use crate::dto::{AppInfo, ProgressEvent};
use crate::error::{AppError, ErrorCode};

const HEADER: &str = "\
// This file is GENERATED by `pnpm bindings` (src-tauri/src/bindings.rs).
// Do not edit it by hand; change the Rust DTOs and regenerate instead.

import type { Channel } from \"@tauri-apps/api/core\";
";

/// A command signature as the frontend sees it.
struct CommandSpec {
    name: &'static str,
    args: Vec<(&'static str, String)>,
    result: String,
}

fn declarations(cfg: &Config) -> Vec<String> {
    vec![
        AppInfo::decl(cfg),
        ProgressEvent::decl(cfg),
        ErrorCode::decl(cfg),
        AppError::decl(cfg),
    ]
}

fn commands(cfg: &Config) -> Vec<CommandSpec> {
    vec![
        CommandSpec {
            name: "get_app_info",
            args: vec![],
            result: AppInfo::name(cfg),
        },
        CommandSpec {
            name: "run_progress_demo",
            args: vec![
                ("operationId", String::name(cfg)),
                ("steps", u32::name(cfg)),
                ("intervalMs", u32::name(cfg)),
                (
                    "onProgress",
                    format!("Channel<{}>", ProgressEvent::name(cfg)),
                ),
            ],
            result: "null".to_owned(),
        },
        CommandSpec {
            name: "cancel_operation",
            args: vec![("operationId", String::name(cfg))],
            result: bool::name(cfg),
        },
    ]
}

fn render_commands(specs: &[CommandSpec]) -> String {
    let mut out = String::from(
        "/** Every backend command: its arguments and its success result. */\nexport interface Commands {\n",
    );
    for spec in specs {
        let args = if spec.args.is_empty() {
            "Record<string, never>".to_owned()
        } else {
            let fields: Vec<String> = spec
                .args
                .iter()
                .map(|(name, ty)| format!("{name}: {ty}"))
                .collect();
            format!("{{ {} }}", fields.join("; "))
        };
        out.push_str(&format!(
            "  {}: {{ args: {args}; result: {} }};\n",
            spec.name, spec.result
        ));
    }
    out.push_str("}\n");
    out
}

/// Renders the full contents of `src/ipc/bindings.ts`.
pub fn render() -> String {
    let cfg = Config::new();
    let mut output = String::from(HEADER);
    for declaration in declarations(&cfg) {
        output.push('\n');
        output.push_str("export ");
        output.push_str(&declaration);
        output.push('\n');
    }
    output.push('\n');
    output.push_str(&render_commands(&commands(&cfg)));
    output
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use super::*;

    #[test]
    fn rendered_bindings_start_with_generated_header() {
        assert!(render().starts_with("// This file is GENERATED"));
    }

    #[test]
    fn exports_every_registered_command() {
        let rendered = render();
        for name in ["get_app_info", "run_progress_demo", "cancel_operation"] {
            assert!(
                rendered.contains(&format!("  {name}: {{ args:")),
                "{name} missing"
            );
        }
    }

    #[test]
    fn bindings_file_is_up_to_date() {
        let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../src/ipc/bindings.ts");
        let on_disk = std::fs::read_to_string(path).unwrap();
        assert!(
            on_disk == render(),
            "src/ipc/bindings.ts is stale: run `pnpm bindings`"
        );
    }
}
